"use client";
import {useState} from "react";
import {createClient} from "@/lib/supabase/client";

type Project={id:string;name:string;website_url:string;description:string;target_customer:string;analysis:any;blueprint:any;created_at:string};

export default function DashboardClient({userEmail,initialProjects}:{userEmail:string;initialProjects:Project[]}){
 const supabase=createClient();
 const [url,setUrl]=useState(""),[desc,setDesc]=useState(""),[target,setTarget]=useState(""),[instruction,setInstruction]=useState(""),[result,setResult]=useState<any>(null),[loading,setLoading]=useState(false),[msg,setMsg]=useState("");
 async function run(mode:"analyze"|"build"|"modify"){
   setLoading(true);setMsg("");
   const res=await fetch("/api/ai",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({mode,url,description:desc,targetCustomer:target,current:result,instruction})});
   const data=await res.json(); setLoading(false);
   if(!res.ok){setMsg(data.error||"AI request failed");return}
   setResult(data.result);
 }
 async function save(){
   if(!result){setMsg("Analyze/build something first.");return}
   if(!supabase){setMsg("Supabase is not configured.");return}
   const {error}=await supabase.from("projects").insert({name:result.productName||"Untitled Product",website_url:url,description:desc,target_customer:target,analysis:result,blueprint:result});
   setMsg(error?error.message:"Project saved.");
 }
 async function logout(){if(!supabase){setMsg("Supabase is not configured.");return};await supabase.auth.signOut();location.href="/login"}
 return <main className="container dashboard">
   <div className="row" style={{justifyContent:"space-between"}}><div><h1>Product Builder</h1><p className="muted">{userEmail}</p></div><button className="btn secondary" onClick={logout}>Logout</button></div>
   <div className="card">
     <input className="input" placeholder="Website URL e.g. https://example.com" value={url} onChange={e=>setUrl(e.target.value)} disabled={!supabase}/>
     <textarea className="textarea" placeholder="What do you want to build?" value={desc} onChange={e=>setDesc(e.target.value)} disabled={!supabase}/>
     <input className="input" placeholder="Target customer" value={target} onChange={e=>setTarget(e.target.value)} disabled={!supabase}/>
     <div className="row"><button className="btn" disabled={loading || !supabase} onClick={()=>run("analyze")}>{loading?"Working...":"Analyze Website"}</button><button className="btn secondary" disabled={loading || !supabase} onClick={()=>run("build")}>Build My Product</button><button className="btn secondary" onClick={save} disabled={!supabase}>Save</button></div>
   </div>
   {result&&<div className="card" style={{marginTop:20}}>
     <h2>{result.productName||"Product Concept"}</h2>
     <div className="result">{JSON.stringify(result,null,2)}</div>
     <h3>Modify with AI</h3>
     <textarea className="textarea" placeholder="Make the design more premium. Add a dashboard..." value={instruction} onChange={e=>setInstruction(e.target.value)} disabled={!supabase}/>
     <button className="btn" onClick={()=>run("modify")} disabled={!supabase}>Apply Change</button>
   </div>}
   {msg&&<p className="small">{msg}</p>}
   <h2 style={{marginTop:45}}>Saved projects</h2>
   <div className="grid">{initialProjects.map(p=><div className="card" key={p.id}><h3>{p.name}</h3><p className="muted small">{p.website_url}</p><p className="muted">{p.description}</p></div>)}</div>
 </main>
}